375	/** Compact rail: avatars only, featured agent first, then a divider and the specialists. */
376	export function RailPanel({ agents, rows, activeKey, onSelect, onNewChat, onToggleCompact }: SidebarPanelProps) {
377	  const stagger = useFirstLoadStagger();
378	  const { primary, specialists } = groupAgents(agents);
379	  const item = (agent: AgentSummary, index: number) => {
