391	              className="relative grid h-12 w-12 shrink-0 place-items-center rounded-[14px] transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:bg-sidebar-accent/60"
392	            />
393	          }
394	        >
395	          {selected ? (
396	            <m.span
397	              layoutId="rail-selected"
398	              transition={SPRING}
399	              aria-hidden="true"
400	              className="absolute inset-0 z-0 rounded-[14px] bg-sidebar-accent"
401	            />
402	          ) : null}
403	          <m.span
404	            className="relative z-[1] inline-flex"
405	            custom={index}
406	            variants={itemVariants}
407	            initial={stagger ? "hidden" : false}
408	            animate="visible"
409	          >
410	            <AgentAvatar agent={agent} size={40} row={rows[agent.key]} />
411	          </m.span>
412	        </TooltipTrigger>
413	        <TooltipContent side="right" sideOffset={8}>
414	          {agent.name}
415	        </TooltipContent>
416	      </Tooltip>
417	    );
418	  };
419	
420	  return (
421	    <div className="flex h-full min-h-0 flex-col items-center">
422	      <div className="flex h-[52px] shrink-0 items-center pt-2">
423	        {onToggleCompact ? (
424	          <button
425	            type="button"
426	            aria-label="Expand sidebar"
427	            title="Expand sidebar"
428	            onClick={onToggleCompact}
429	            className={iconButton}
