462	  const [theme, setTheme] = useState<ResolvedAppearance>(() =>
463	    document.documentElement.dataset.theme === "light" ? "light" : "dark",
464	  );
465	  const next = theme === "dark" ? "light" : "dark";
466	  const label = theme === "dark" ? "Light mode" : "Dark mode";
467	  const icon = theme === "dark" ? <Sun size={15} strokeWidth={1.8} /> : <Moon size={15} strokeWidth={1.8} />;
468	  if (compact) {
469	    return (
470	      <button
471	        type="button"
472	        aria-label={label}
473	        title={label}
474	        onClick={() => setTheme(setUiAppearance(next))}
475	        className="grid h-10 w-10 place-items-center rounded-xl text-foreground/80 transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:bg-sidebar-accent"
476	      >
477	        {icon}
478	      </button>
479	    );
480	  }
481	  return (
482	    <button
483	      type="button"
484	      onClick={() => setTheme(setUiAppearance(next))}
485	      className="mx-3 mb-3 flex shrink-0 items-center gap-3 rounded-xl px-2.5 py-2 transition-colors duration-(--motion-fast) ease-(--ease-standard) hover:bg-sidebar-accent"
486	    >
487	      <span className="grid h-[30px] w-[30px] place-items-center rounded-lg bg-accent text-foreground/80">{icon}</span>
488	      <span className="text-[14px] font-medium text-foreground/90">{label}</span>
489	    </button>
490	  );
491	}
492	
493	function previewText(message: UIMessage): string {
494	  const plain = messageText(message)
495	    .replace(/[#>*_`|]/g, "")
496	    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
497	    .replace(/\s+/g, " ")
498	    .trim();
499	  return plain && message.role === "user" ? `You: ${plain}` : plain;
500	}
501	
502	/** Time for today, weekday within a week, else a short date (as in rakazo's roster). */
503	function formatRosterTime(timestamp: number): string {
504	  const date = new Date(timestamp);
505	  const now = new Date();
506	  if (date.toDateString() === now.toDateString()) {
507	    return date.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" });
508	  }
509	  const days = (now.getTime() - timestamp) / 86_400_000;
510	  if (days < 7) return date.toLocaleDateString(undefined, { weekday: "short" });
511	  return date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
512	}
