import type { AgentSummary } from "@/hooks/useAgents";

/** The orchestrator gets the featured tile; every other agent is listed as a specialist. */
export const PRIMARY_AGENT_KEY = "assistant";

/** Sidebar geometry (px). */
export const SIDEBAR = {
  /** Expanded width bounds and default. */
  MIN: 240,
  MAX: 400,
  DEFAULT: 284,
  /** Compact rail width. */
  RAIL: 76,
  /** Dragging an expanded edge below this snaps to the rail (MIN - 40). */
  SNAP_TO_RAIL: 200,
  /** Dragging the rail's edge past this snaps back to the last expanded width. */
  SNAP_TO_EXPANDED: 140,
  /** Keyboard resize steps. */
  STEP: 16,
  STEP_LARGE: 48,
} as const;

export const clampWidth = (width: number) => Math.min(SIDEBAR.MAX, Math.max(SIDEBAR.MIN, Math.round(width)));

export function groupAgents(agents: AgentSummary[]): { primary: AgentSummary[]; specialists: AgentSummary[] } {
  return {
    primary: agents.filter((agent) => agent.key === PRIMARY_AGENT_KEY),
    specialists: agents.filter((agent) => agent.key !== PRIMARY_AGENT_KEY),
  };
}

const WIDTH_KEY = "nlhack.sidebarWidth";
const COMPACT_KEY = "nlhack.sidebarCompact";
/** Pre-rail preference ("hidden" sidebar); now maps to the compact rail. */
const LEGACY_COLLAPSED_KEY = "nlhack.sidebarCollapsed";

function read(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function write(key: string, value: string) {
  try {
    localStorage.setItem(key, value);
  } catch {
    // Layout preferences are a convenience; ignore blocked storage.
  }
}

export function readSidebarWidth(): number {
  const stored = Number(read(WIDTH_KEY));
  return Number.isFinite(stored) && stored > 0 ? clampWidth(stored) : SIDEBAR.DEFAULT;
}

export function readSidebarCompact(): boolean {
  const stored = read(COMPACT_KEY);
  return stored === null ? read(LEGACY_COLLAPSED_KEY) === "true" : stored === "true";
}

export function writeSidebarLayout(width: number, compact: boolean) {
  write(WIDTH_KEY, String(clampWidth(width)));
  write(COMPACT_KEY, String(compact));
}
// Loaded on demand by <LazyMotion> (see main.tsx) so the feature bundle stays out of the
// initial chunk. domMax (not domAnimation) because the shell uses layout and layoutId.
import { domMax } from "motion/react";

export default domMax;
// Modified from rakazo (Apache-2.0), github.com/elie222/rakazo@912c977
import type { GrokColorDef } from "@/lib/avatar";
import {
  ACTIVE_RUN_STATUSES,
  avatarIdentitySeed,
  DEFAULT_GROK_BOT_COLOR,
  GROK_BOT_COLORS,
  GROK_COLOR_LIST,
  organicAvatarPath,
  resolvePersonaColorDef,
  SHIPPED_BOT_AVATAR_CENTER,
  SHIPPED_BOT_AVATAR_SHAPE_KEYS,
  SHIPPED_BOT_AVATAR_SHAPES,
  SHIPPED_BOT_AVATAR_VIEWBOX,
  shippedBotAvatarShapePath,
  shippedHash,
} from "@/lib/avatar";
import { tokens } from "@/lib/tokens";
import type { CSSProperties } from "react";
import { memo, useId, useMemo, useSyncExternalStore } from "react";
import type { AvatarStyle } from "./avatar-style";
import { useAvatarStyle } from "./avatar-style";
import { cn } from "@/lib/utils";

export type { GrokColorDef };
export { DEFAULT_GROK_BOT_COLOR, GROK_BOT_COLORS, GROK_COLOR_LIST, resolvePersonaColorDef };

export const GROK_SHAPES = SHIPPED_BOT_AVATAR_SHAPES;
export const SHIPPED_SHAPE_KEYS = SHIPPED_BOT_AVATAR_SHAPE_KEYS;
const VIEWBOX = SHIPPED_BOT_AVATAR_VIEWBOX;
const CENTER = SHIPPED_BOT_AVATAR_CENTER;

export const GROK_MASCOT_SHAPES = SHIPPED_SHAPE_KEYS.map(
  (k) => GROK_SHAPES[k] ?? FALLBACK_SHAPE_PATH,
);

const FALLBACK_SHAPE_PATH = GROK_SHAPES.hex ?? "";

export function resolvePersonaShape(identity: string, explicitShape?: string | null): string {
  if (explicitShape) {
    const explicit = GROK_SHAPES[explicitShape];
    if (explicit) return explicit;
  }
  let hash = shippedHash(identity);
  hash = Math.imul(hash ^ (hash >>> 16), 73244475);
  hash = Math.imul(hash ^ (hash >>> 13), 3266489909);
  const shapeIndex = ((hash ^ (hash >>> 16)) >>> 0) % SHIPPED_SHAPE_KEYS.length;
  const key = SHIPPED_SHAPE_KEYS[shapeIndex] ?? "hex";
  return GROK_SHAPES[key] ?? FALLBACK_SHAPE_PATH;
}

export function parseBotAvatar(
  rawColor: string,
  _identity?: string,
): {
  color: string;
  shapeIndex?: number;
  isImage: boolean;
  imageUrl?: string;
} {
  if (!rawColor) return { color: "#F97316", isImage: false };
  // Only data: image URLs are rendered. Arbitrary http(s)/blob values in `color`
  // must not become <img src> (SSRF / tracking when other members view the bot).
  if (rawColor.startsWith("data:image/")) {
    return { color: "#F97316", isImage: true, imageUrl: rawColor };
  }
  if (rawColor.includes("::shape_")) {
    const parts = rawColor.split("::shape_");
    const rawShapeIdx = parts[1] ?? "0";
    const parsedShapeIdx = /^\d+$/.test(rawShapeIdx) ? Number(rawShapeIdx) : 0;
    const shapeIdx = Number.isSafeInteger(parsedShapeIdx) ? parsedShapeIdx : 0;
    return {
      color: parts[0] || "#F97316",
      shapeIndex: shapeIdx % SHIPPED_SHAPE_KEYS.length,
      isImage: false,
    };
  }
  return { color: rawColor, isImage: false };
}

